change_filament_gcode:
{if toolchange_count > 1}
{if enable_prime_tower}
T[next_extruder]
M109 S[new_filament_temp]
{else}
{if position[1] - 5 >= 0 && position[1] + 5 <= 260}
G2 Z{z_after_toolchange + 0.4} I0.86 J0.86 P1 F30000
{else}
{if position[1] + 5 <= 260}
G1 Y{position[1] + 5} Z{z_after_toolchange + 0.4} F30000
{else}
G1 Y{position[1] - 5} Z{z_after_toolchange + 0.4} F30000
{endif}
{endif}
SET_VELOCITY_LIMIT ACCEL=10000 ACCEL_TO_DECEL=10000
G0 X266 F30000
G0 X277 F2400
T[next_extruder]

M83
; FLUSH_START
SET_VELOCITY_LIMIT ACCEL=5000 ACCEL_TO_DECEL=5000
M106 S70
; Use the new filament printing temperature
M109 S[new_filament_temp]

M400
M106 S200
{if flush_length_1 + flush_length_2 + flush_length_3 + flush_length_4 + flush_length_5 > 40}
G1 E{flush_length_1 + flush_length_2 + flush_length_3 + flush_length_4 + flush_length_5 - 10} F{new_filament_e_feedrate * 0.8}
{else}
G1 E37 F{new_filament_e_feedrate * 0.8}
{endif}

M400
G1 E-[new_retract_length_toolchange] F1800
M106 S200
{if filament_type[previous_extruder] == "PETG"}
G4 P3000
{else}
G4 P2000
{endif}
M106 S70

; FLUSH_END

; WIPE
SET_VELOCITY_LIMIT ACCEL=10000 ACCEL_TO_DECEL=10000
G0 X266 F30000
G0 X277 F2400
G0 X266 F30000
G0 X277 F2400
G0 X266 F30000

SET_VELOCITY_LIMIT ACCEL=5000 ACCEL_TO_DECEL=5000
{endif}
{endif}

machine_start_gcode:
M140 S0
M104 S0 
START_PRINT EXTRUDER_TEMP=[nozzle_temperature_initial_layer] BED_TEMP=[bed_temperature_initial_layer_single]
T[initial_no_support_extruder]
M104 S[nozzle_temperature_initial_layer]
M83
G1 Y-2 F12000
G1 X150 F30000
G1 Z0.2 F600
G1 X120 Y-2 E15 F{filament_max_volumetric_speed[initial_extruder]/0.3*60*0.1}
G1 X115 E.3742  F{outer_wall_volumetric_speed/(0.3*0.5)/4*60}
G1 X110 E.3742  F{outer_wall_volumetric_speed/(0.3*0.5)*60}
G1 X105 E.3742  F{outer_wall_volumetric_speed/(0.3*0.5)/4*60}
G1 X100 E.3742  F{outer_wall_volumetric_speed/(0.3*0.5)*60}
G1 X95 E.3742  F{outer_wall_volumetric_speed/(0.3*0.5)/4*60}
G91
G1 X-1 Z-0.3
G1 X-4
G92 E0
